def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    if not alive_opponents:
        return float(min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from immediate previous_trace
    yesterday_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                yesterday_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Determine pressure level from yesterday
    aggressive = highest_prev_bid >= DAILY_SALARY * 0.85

    # Supply-based aggressiveness: closer to MAX_SUPPLY means more water likely, so bid slightly lower.
    supply_ratio = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Base target bid
    if aggressive:
        if my_hp > 4.0 and my_no_water_days <= 1:
            # Stay just under their aggressive ceiling to win without overspending
            target = min(my_budget, DAILY_SALARY * (0.28 + 0.12 * (1.0 - supply_ratio)))
        else:
            # If I'm under pressure, match the aggressive band
            target = min(my_budget, DAILY_SALARY * (0.85 + 0.05 * (1.0 - supply_ratio)))
    else:
        if my_hp <= 2.5 or my_no_water_days >= 2:
            target = min(my_budget, DAILY_SALARY * 0.9)
        else:
            # Conservative when others weren't bidding hard
            target = min(my_budget, max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5))

    # If supply is tight (near MIN_SUPPLY), increase bid modestly
    if supply <= (MIN_SUPPLY + 2.0):
        target = min(my_budget, target * 1.08)

    # Final safety clamps
    if my_budget <= 0.0:
        return 0.0

    # Ensure bid is non-negative
    if target < 0.0:
        target = 0.0

    return float(target)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_hp = my_status['hp']
    my_budget = my_status['budget']
    current_day = day_context['day']
    current_supply = day_context['supply']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_budget, DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev_trace = opp.get('previous_trace', {})
        if prev_trace and prev_trace.get('bid') is not None:
            yesterday_bids.append(prev_trace['bid'])

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    bid = DAILY_SALARY * 0.6 # A solid base bid

    # Adjust bid based on my HP
    if my_hp <= 2:
        bid = DAILY_SALARY * 0.95 # Critical HP, bid very aggressively
    elif my_hp <= 4:
        bid = DAILY_SALARY * 0.85 # Low HP, bid aggressively
    elif my_hp <= 6 and current_day > EPISODE_DAYS / 2:
        bid = DAILY_SALARY * 0.75 # Mid-game, slightly low HP

    # Adjust bid based on supply scarcity
    num_full_water_slots = int(current_supply // WATER_REQ)
    if num_full_water_slots < len(alive_opponents) + 1:
        if current_supply < WATER_REQ * 1.5:
            bid = max(bid, DAILY_SALARY * 0.75)
        elif current_supply < WATER_REQ * 2:
            bid = max(bid, DAILY_SALARY * 0.65)

    # Adjust bid based on opponent's previous bids
    if highest_prev_bid > 0:
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_hp > 5:
                bid = max(bid, highest_prev_bid + 5)
            else:
                bid = max(bid, highest_prev_bid + 10)
        elif highest_prev_bid > DAILY_SALARY * 0.5:
            bid = max(bid, highest_prev_bid + 2)

    # Adjust for end game
    remaining_days = EPISODE_DAYS - current_day
    if remaining_days <= 2:
        if my_hp > 0:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.99)

    # Final budget check
    bid = min(bid, my_budget)

    # Ensure bid is at least a minimal amount if budget allows
    if bid < DAILY_SALARY * 0.1 and my_budget > DAILY_SALARY * 0.1:
        bid = DAILY_SALARY * 0.1

    return bid

